import {
  createContext,
  forwardRef,
  useCallback,
  useContext,
  useEffect,
  useImperativeHandle,
  useMemo,
  useRef,
} from 'react';
import { flushSync } from 'react-dom';

const ROOT_MARGIN = '2000px';
const BG_BATCH_SIZE = 5;
const NEARBY_MOUNT_RADIUS = 3000;

const processBatch = (
  items: (() => void)[],
  batchSize: number,
): Promise<void> => {
  if (items.length === 0) return Promise.resolve();
  return new Promise((resolve) => {
    let index = 0;
    const next = () => {
      const end = Math.min(index + batchSize, items.length);
      for (let i = index; i < end; i++) items[i]();
      index = end;
      if (index < items.length) {
        setTimeout(next, 0);
      } else {
        requestAnimationFrame(() => resolve());
      }
    };
    setTimeout(next, 0);
  });
};

interface LazyMountContextValue {
  register: (id: string, mount: () => void) => void;
  unregister: (id: string) => void;
  observe: (id: string, element: HTMLElement) => void;
  scrollToSlide: (id: string) => void;
  mountAll: () => Promise<void>;
}

const NOOP_CONTEXT: LazyMountContextValue = {
  register: () => undefined,
  unregister: () => undefined,
  observe: () => undefined,
  scrollToSlide: () => undefined,
  mountAll: () => Promise.resolve(),
};

const LazyMountContext = createContext<LazyMountContextValue>(NOOP_CONTEXT);

export const useLazyMount = (): LazyMountContextValue =>
  useContext(LazyMountContext);

export interface LazyMountHandle {
  scrollToSlide: (id: string) => void;
  mountAll: () => Promise<void>;
}

interface LazyMountProviderProps {
  children: React.ReactNode;
}

export const LazyMountProvider = forwardRef<
  LazyMountHandle,
  LazyMountProviderProps
>(({ children }, ref) => {
  const registry = useRef(new Map<string, () => void>());
  const mountedIds = useRef(new Set<string>());
  const elementMap = useRef(new Map<string, Element>());
  const observerRef = useRef<IntersectionObserver | null>(null);

  const getObserver = useCallback(() => {
    if (!observerRef.current && typeof IntersectionObserver !== 'undefined') {
      observerRef.current = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            if (!entry.isIntersecting) return;
            const id = (entry.target as HTMLElement).dataset.pageName;
            if (!id) return;
            const mountFn = registry.current.get(id);
            if (mountFn) mountFn();
            observerRef.current?.unobserve(entry.target);
            elementMap.current.delete(id);
          });
        },
        { rootMargin: ROOT_MARGIN },
      );
    }
    return observerRef.current;
  }, []);

  useEffect(() => {
    return () => observerRef.current?.disconnect();
  }, []);

  const register = useCallback((id: string, mount: () => void) => {
    registry.current.set(id, () => {
      mount();
      mountedIds.current.add(id);
    });
  }, []);

  const unregister = useCallback((id: string) => {
    registry.current.delete(id);
    mountedIds.current.delete(id);
    const el = elementMap.current.get(id);
    if (el) {
      observerRef.current?.unobserve(el);
      elementMap.current.delete(id);
    }
  }, []);

  const observe = useCallback(
    (id: string, element: HTMLElement) => {
      elementMap.current.set(id, element);
      getObserver()?.observe(element);
    },
    [getObserver],
  );

  const scrollToSlide = useCallback((id: string) => {
    const mountFn = registry.current.get(id);
    if (mountFn) {
      flushSync(() => mountFn());
    }

    const target = document.querySelector(`[data-page-name="${id}"]`);
    if (!target) return;
    const targetTop = target.getBoundingClientRect().top;

    const placeholders = document.querySelectorAll('[data-lazy-placeholder]');
    if (placeholders.length) {
      flushSync(() => {
        placeholders.forEach((ph) => {
          if (
            Math.abs(ph.getBoundingClientRect().top - targetTop) <
            NEARBY_MOUNT_RADIUS
          ) {
            const phId = (ph as HTMLElement).dataset.pageName;
            if (phId) registry.current.get(phId)?.();
          }
        });
      });
    }

    const el = document.querySelector(`[data-page-name="${id}"]`);
    el?.scrollIntoView({ block: 'start' });
  }, []);

  const mountAll = useCallback((): Promise<void> => {
    const unmounted: (() => void)[] = [];
    registry.current.forEach((mount, id) => {
      if (!mountedIds.current.has(id)) unmounted.push(mount);
    });
    return processBatch(unmounted, BG_BATCH_SIZE);
  }, []);

  useImperativeHandle(ref, () => ({ scrollToSlide, mountAll }), [
    scrollToSlide,
    mountAll,
  ]);

  const value = useMemo(
    () => ({ register, unregister, observe, scrollToSlide, mountAll }),
    [register, unregister, observe, scrollToSlide, mountAll],
  );

  return (
    <LazyMountContext.Provider value={value}>
      {children}
    </LazyMountContext.Provider>
  );
});

LazyMountProvider.displayName = 'LazyMountProvider';
